-- 78 Echo Canyon: the hiker walks from camp into the canyon and calls. The
-- canyon is an audio_zone lending the sfx bus an echo, the radio plays on the
-- music bus made an AM set by its effects, and every footstep is one clip
-- with a variation. The rings and words are drawn at the echo's own times.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/78-echo-canyon.scene"
local GROUND, CANYON_X = -200.0, 300.0
local ECHO_TIME, ECHO_RETURN = 0.42, 0.45
local CAMP_X = -300
local SPEED = 115
local STEP = "sounds/canyon_step.wav"
local CALL = "sounds/canyon_shout.wav"
local WORDS = { "HEY!", "HELLO!", "ANYONE?", "YOO-HOO!" }

local captions = true
local echo_on, radio_on, varied = true, true, true
local hiker, caller, dust, call_text, zone, status
local rings, echoes = {}, {}
local x, dir, state, wait, t = CAMP_X, 1, "walk", 1.0, 0
local step_clock, call_at, called, word = 0, -100, false, 1

local function radio(on)
    local function fx(name, v) Audio.set_bus_effect("music", name, on and v or 0) end
    fx("distortion", 0.45)
    fx("eq_low", -20)
    fx("eq_mid", 7)
    fx("eq_high", -16)
    fx("compress", 0.75)
end

local function show_status()
    UI.set_text(status, "echo " .. (echo_on and "on" or "off") .. "   radio " .. (radio_on and "AM" or "clean")
        .. "   steps " .. (varied and "varied" or "all alike"))
end

local function call_out()
    word = word % #WORDS + 1
    Audio.play_sound(CALL, 0.9)
    call_at = t
    Text.set(call_text, WORDS[word])
    for k = 1, #echoes do Text.set(echoes[k], string.lower(WORDS[word])) end
end

function init(entity)
    hiker = Entity.find_by_name("Hiker")
    caller = Entity.find_by_name("HikerCall")
    dust = Entity.find_by_name("Dust")
    call_text = Entity.find_by_name("Call")
    zone = Entity.find_by_name("CanyonZone")
    status = Entity.find_by_name("Status")
    for k = 1, 5 do
        rings[k] = Entity.find_by_name("Ring" .. (k - 1))
        echoes[k] = Entity.find_by_name("Echo" .. (k - 1))
    end
    Audio.set_variation(STEP, 3, 0.35)
    radio(true)
    show_status()
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("E") then
        echo_on = not echo_on
        Transform.set_position(zone, echo_on and CANYON_X or 5000, 0)
        show_status()
    end
    if Input.is_key_just_pressed("R") then radio_on = not radio_on; radio(radio_on); show_status() end
    if Input.is_key_just_pressed("V") then
        varied = not varied
        if varied then Audio.set_variation(STEP, 3, 0.35) else Audio.set_variation(STEP, 0, 0) end
        show_status()
    end
    if Input.is_key_just_pressed("Space") then call_out() end

    -- Walk to the canyon, call twice, walk back, rest by the fire.
    local walking = false
    if state == "walk" then
        local goal = dir > 0 and CANYON_X or CAMP_X
        x = x + dir * SPEED * dt
        walking = true
        if (dir > 0 and x >= goal) or (dir < 0 and x <= goal) then
            x = goal
            state, wait, called = "stay", dir > 0 and 4.5 or 2.5, false
        end
    else
        wait = wait - dt
        if state == "stay" and dir > 0 and not called and wait < 4.0 then call_out(); called = true end
        if wait <= 0 then state, dir = "walk", -dir end
    end
    if walking then
        step_clock = step_clock + dt
        if step_clock > 0.42 then
            step_clock = 0
            Audio.play_sound(STEP, 0.55)
            Particles.emit_burst(dust, 4)
        end
    end
    local bob = walking and math.abs(math.sin(t * 7.5)) * 4 or 0
    local calling = t - call_at < 0.9
    for _, e in ipairs({ hiker, caller }) do
        Transform.set_position(e, x, GROUND + bob)
        Transform.set_scale(e, dir, 1)
    end
    Sprite.set_color(hiker, 1, 1, 1, calling and 0 or 1)
    Sprite.set_color(caller, 1, 1, 1, calling and 1 or 0)
    Transform.set_position(dust, x, GROUND + 4)
    Transform.set_position(call_text, x + dir * 20, GROUND + 150 + (t - call_at) * 30)
    Text.set_color(call_text, 1, 0.95, 0.85, math.max(0, 1 - (t - call_at) / 1.2))

    -- The canyon answers: a ring and a fainter word at each echo, while
    -- the caller is in it and its echo is on.
    local inside = echo_on and math.abs(x - CANYON_X) < 200
    for k = 1, 5 do
        local age = t - call_at - k * ECHO_TIME
        local strength = (inside and age >= 0 and age < 1.2) and ECHO_RETURN ^ (k - 1) or 0
        local s = 0.4 + age * 2.2
        Transform.set_scale(rings[k], s, s)
        Sprite.set_color(rings[k], 1.0, 0.72, 0.36, strength * 0.8 * (1 - age / 1.2))
        Transform.set_position(echoes[k], CANYON_X + ((k % 2 == 0) and -1 or 1) * (60 + k * 28), 150 + k * 34 + age * 20)
        Text.set_color(echoes[k], 1.0, 0.86, 0.66, strength * (1 - age / 1.2))
    end
end
